<script setup lang="ts">definePageMeta({layout:'admin'});const {data,refresh}=await useFetch('/api/admin/categories',{transform:(r:any)=>r.data});const form=reactive({id:'',name:'',slug:'',description:'',sortOrder:0,isActive:true}),message=ref(''),error=ref('');watch(()=>form.name,v=>{if(!form.id)form.slug=v.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')});function edit(x:any){Object.assign(form,x);scrollTo({top:0,behavior:'smooth'})}function reset(){Object.assign(form,{id:'',name:'',slug:'',description:'',sortOrder:0,isActive:true})}async function save(){error.value='';try{await $fetch(form.id?`/api/admin/categories/${form.id}`:'/api/admin/categories',{method:form.id?'PUT':'POST',body:form});message.value='Kategori berhasil disimpan.';reset();refresh()}catch(e:any){error.value=e.data?.statusMessage||'Gagal menyimpan.'}}async function remove(id:string){if(!confirm('Hapus kategori ini?'))return;try{await $fetch(`/api/admin/categories/${id}`,{method:'DELETE'});refresh()}catch(e:any){error.value=e.data?.statusMessage}}</script><template><div class="admin-page"><AdminPageHeader title="Kategori" description="Atur kelompok produk di katalog."/><form class="panel form" @submit.prevent="save"><div><label class="label">Nama *</label><input v-model="form.name" class="field" required minlength="2"></div><div><label class="label">Slug *</label><input v-model="form.slug" class="field" required></div><div><label class="label">Urutan</label><input v-model.number="form.sortOrder" class="field" type="number" min="0"></div><div class="wide"><label class="label">Deskripsi</label><input v-model="form.description" class="field"></div><label class="check"><input v-model="form.isActive" type="checkbox"> Aktif</label><div class="actions"><button class="btn btn-primary">{{form.id?'Perbarui':'Tambah'}} kategori</button><button v-if="form.id" class="btn btn-outline" type="button" @click="reset">Batal</button></div><p v-if="message" class="success">{{message}}</p><p v-if="error" class="error">{{error}}</p></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Nama</th><th>Slug</th><th>Urutan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-for="x in data" :key="x.id"><td><b>{{x.name}}</b></td><td>{{x.slug}}</td><td>{{x.sortOrder}}</td><td>{{x.isActive?'Aktif':'Nonaktif'}}</td><td><button @click="edit(x)">Edit</button> · <button @click="remove(x.id)">Hapus</button></td></tr></tbody></table></div></div></template><style scoped>.form{padding:1rem;display:grid;grid-template-columns:1fr 1fr 130px;gap:1rem;align-items:end}.wide{grid-column:1/-1}.check{align-self:center}.actions{display:flex;gap:.5rem}.success{color:var(--success)}table button{border:0;background:none;color:var(--gold-dark)}@media(max-width:700px){.form{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
